let n = 0;

boton.onclick = () => {
  n++;
  boton.textContent = n;
};

function Contador() {
  const [n, setN] = useState(0);
  const sumar = () => setN(n + 1);
  return (
    <button onClick={sumar}>
      {n}
    </button>
  );
}

@Component({
  template: `
    <button (click)="n = n + 1">
      {{ n }}
    </button>
  `,
})
class Contador {
  n = 0;
}

